content:
{
  "is_open_solicitation": true,
  "buyer": "Achievement First",
  "title": "Request for Proposals: Website Redesign & Ecosystem Development",
  "due_date": "2026-11-09",
  "fit_score": 15,
  "why_fit": [
    "Core service includes website redesign and WordPress maintenance",
    "Mobile-first, hand-coded approach aligns with performance targets",
    "Experience with structured data and SEO/AEO optimization",
    "Hosting with daily backups, SSL, and monitoring matches some requirements"
  ],
  "gaps": [
    "No demonstrated experience with enterprise multi-site ecosystems (41 schools + regional hubs + network)",
    "No evidence of WCAG 2.2 AA compliance implementation",
    "No multilingual (English/Spanish) site experience",
    "No case studies with federated CMS or large-scale non-profit/education clients",
    "Missing integration experience with SchoolMint, HubSpot, Greenhouse, Salesforce, Fundraise Up, ParentSquare, Infinite Campus, Okta",
    "No Find-a-School interactive map/geolocation or faceted search portfolio",
    "No enterprise security stack (SSO/MFA/SCIM, CI/CD, Dev/Staging/Prod environments)",
    "Likely insufficient insurance (General Liability, Cyber Liability, E&O) for this scale",
    "Team capacity appears sized for small business sites (10 pages in 3-4 weeks), not 41+ sites"
  ],
  "requirements": [
    "Proposal in PDF via email to Jacqui Alessi by November 9, 2026",
    "Executive Summary, Agency Profile & Team, Three Case Studies, Technical Solution, Work Plan & Schedule, Pricing & TCO, Terms & Compliance",
    "Three relevant case studies with multi-site implementations, live URLs, client references",
    "Demonstrated multi-tier architecture and content governance model",
    "WCAG 2.2 AA compliance approach",
    "Security practices, data protection, insurance verification, IP ownership confirmation",
    "Proposals valid for 90 days post-submission"
  ],
  "evidence": [
    {
      "claim": "RFP seeks vendor for unified ecosystem across network, regional hubs, and 41 school sites",
      "quote": "The solution will comprise a main network website, regional hubs, and 41 distinct school-specific websites under a central governance model."
    },
    {
      "claim": "Proposal deadline is November 9, 2026",
      "quote": "Proposal Submission Deadline | November 9, 2026"
    },
    {
      "claim": "Requires three case studies with multi-site implementations",
      "quote": "Three relevant case studies demonstrating multi-site, federated, or enterprise CMS implementations."
    },
    {
      "claim": "Mandates WCAG 2.2 AA compliance verified via automated and manual testing",
      "quote": "Full adherence to WCAG 2.2 Level AA standards verified via automated tools and manual screen-reader/keyboard testing."
    },
    {
      "claim": "Requires enterprise security with SSO/MFA/SCIM and Okta integration",
      "quote": "Scalable login access to the backend functions of the platform; distributed admin access to the 41 school sites"
    },
    {
      "claim": "Demands daily automated backups with 30-day retention, RPO 24h, RTO 8h",
      "quote": "minimum requirements include daily automated backups across all 41 school sites plus network and regional tiers, 30-day retention minimum, Recovery Point Objective [RPO] of 24 hours or less, and Recovery Time Objective [RTO] of 8 hours or less"
    },
    {
      "claim": "Company hand-builds websites and offers WordPress hosting with daily backups",
      "quote": "Hosting on servers the company runs and monitors, with daily backups, SSL, business email, domain renewals and WordPress maintenance."
    },
    {
      "claim": "Company delivers website redesigns up to 10 pages in 3 to 4 weeks",
      "quote": "a full redesign of up to 10 pages in 3 to 4 weeks"
    }
  ]
}
